import math


def solve_tridiagonal(lower, diagonal, upper, values):
    sequences = []
    for item in (lower, diagonal, upper, values):
        try:
            sequences.append(list(item))
        except TypeError:
            raise TypeError("all arguments must be iterable") from None
    a, b, c, d = sequences
    n = len(b)
    if len(d) != n or len(a) != max(0, n - 1) or len(c) != max(0, n - 1):
        raise ValueError("incompatible lengths")
    for sequence in sequences:
        for number in sequence:
            if isinstance(number, bool) or not isinstance(number, (int, float)):
                raise TypeError("entries must be numeric")
            if not math.isfinite(number):
                raise ValueError("entries must be finite")
    if n == 0:
        return []
    cp = [0.0] * max(0, n - 1)
    dp = [0.0] * n
    pivot = float(b[0])
    if pivot == 0.0:
        raise ZeroDivisionError("zero pivot")
    if n > 1:
        cp[0] = c[0] / pivot
    dp[0] = d[0] / pivot
    for i in range(1, n):
        pivot = b[i] - a[i - 1] * cp[i - 1]
        if pivot == 0.0:
            raise ZeroDivisionError("zero pivot")
        if i < n - 1:
            cp[i] = c[i] / pivot
        dp[i] = (d[i] + a[i - 1] * dp[i - 1]) / pivot
    result = [0.0] * n
    result[-1] = dp[-1]
    for i in range(n - 2, -1, -1):
        result[i] = dp[i] - cp[i] * result[i + 1]
    return result
```

